// frontend/src/pages/AdminProducts.js

import React, { useEffect, useState } from "react";
import {
  getProducts,
  createProduct,
  updateProduct,
  deleteProduct
} from "../services/api";

export default function AdminProducts() {
  const [products, setProducts] = useState([]);
  const [newProduct, setNewProduct] = useState({
    Name: "",
    Description: "",
    Price: "",
    Category: "",
    ImageUrl: "",
    IsAvailable: true
  });

  // 1) Încarcă produsele la mount
  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const res = await getProducts();
      setProducts(res.data);
    } catch (err) {
      console.error("Eroare la încărcare produse:", err);
    }
  };

  // 2) Handle creare produs nou
  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      await createProduct({
        Name:        newProduct.Name,
        Description: newProduct.Description,
        Price:       parseFloat(newProduct.Price),
        Category:    newProduct.Category,
        ImageUrl:    newProduct.ImageUrl,
        IsAvailable: newProduct.IsAvailable
      });
      setNewProduct({
        Name: "",
        Description: "",
        Price: "",
        Category: "",
        ImageUrl: "",
        IsAvailable: true
      });
      fetchProducts();
    } catch (err) {
      console.error("Eroare la creare produs:", err);
    }
  };

  // 3) Handle update produs (numai câteva câmpuri, ca exemplu)
  const handleUpdate = async (id, field, value) => {
    try {
      // copiem produsul care se modifică
      const prod = products.find((p) => p.ProductId === id);
      if (!prod) return;
      const updated = { ...prod, [field]: value };
      await updateProduct(id, {
        Name:        updated.Name,
        Description: updated.Description,
        Price:       parseFloat(updated.Price),
        Category:    updated.Category,
        ImageUrl:    updated.ImageUrl,
        IsAvailable: updated.IsAvailable
      });
      fetchProducts();
    } catch (err) {
      console.error("Eroare la update produs:", err);
    }
  };

  // 4) Handle ștergere produs
  const handleDelete = async (id) => {
    if (!window.confirm("Sigur vrei să ștergi acest produs?")) return;
    try {
      await deleteProduct(id);
      fetchProducts();
    } catch (err) {
      console.error("Eroare la ștergere produs:", err);
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <h2>🔧 Admin: Gestionare Produse</h2>

      {/* Formular simplu pentru creare produs */}
      <form onSubmit={handleCreate} style={{ marginBottom: 20 }}>
        <h3>Adaugă Produs Nou</h3>
        <div>
          <input
            type="text"
            placeholder="Denumire"
            value={newProduct.Name}
            onChange={(e) =>
              setNewProduct({ ...newProduct, Name: e.target.value })
            }
            required
            style={{ marginRight: 8 }}
          />
          <input
            type="text"
            placeholder="Descriere"
            value={newProduct.Description}
            onChange={(e) =>
              setNewProduct({ ...newProduct, Description: e.target.value })
            }
            required
            style={{ marginRight: 8, width: 300 }}
          />
        </div>
        <div style={{ marginTop: 8 }}>
          <input
            type="number"
            step="0.01"
            placeholder="Preț"
            value={newProduct.Price}
            onChange={(e) =>
              setNewProduct({ ...newProduct, Price: e.target.value })
            }
            required
            style={{ marginRight: 8, width: 100 }}
          />
          <input
            type="text"
            placeholder="Categorie"
            value={newProduct.Category}
            onChange={(e) =>
              setNewProduct({ ...newProduct, Category: e.target.value })
            }
            required
            style={{ marginRight: 8 }}
          />
          <input
            type="text"
            placeholder="ImageUrl (ex: /images/pizza.png)"
            value={newProduct.ImageUrl}
            onChange={(e) =>
              setNewProduct({ ...newProduct, ImageUrl: e.target.value })
            }
            required
            style={{ marginRight: 8, width: 200 }}
          />
          <label style={{ marginRight: 8 }}>
            <input
              type="checkbox"
              checked={newProduct.IsAvailable}
              onChange={(e) =>
                setNewProduct({ ...newProduct, IsAvailable: e.target.checked })
              }
            />{" "}
            Disponibil
          </label>
          <button type="submit">Crează</button>
        </div>
      </form>

      {/* Tabel produse */}
      <table
        style={{
          width: "100%",
          borderCollapse: "collapse",
          textAlign: "left"
        }}
      >
        <thead>
          <tr style={{ borderBottom: "2px solid #333" }}>
            <th style={{ padding: "8px" }}>ID</th>
            <th style={{ padding: "8px" }}>Poză</th>
            <th style={{ padding: "8px" }}>Denumire</th>
            <th style={{ padding: "8px" }}>Descriere</th>
            <th style={{ padding: "8px" }}>Preț</th>
            <th style={{ padding: "8px" }}>Categorie</th>
            <th style={{ padding: "8px" }}>Disponibil</th>
            <th style={{ padding: "8px" }}>Acțiuni</th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => (
            <tr key={p.ProductId} style={{ borderBottom: "1px solid #ccc" }}>
              <td style={{ padding: "8px" }}>{p.ProductId}</td>

              {/* Afișează imaginea prin URL-ul din baza de date */}
              <td style={{ padding: "8px" }}>
                {p.ImageUrl ? (
                  <img
                    src={p.ImageUrl}
                    alt={p.Name}
                    style={{ width: 60, height: 60, objectFit: "cover" }}
                  />
                ) : (
                  <span>(fără poză)</span>
                )}
              </td>

              <td style={{ padding: "8px" }}>
                <input
                  type="text"
                  value={p.Name}
                  onChange={(e) =>
                    handleUpdate(p.ProductId, "Name", e.target.value)
                  }
                  style={{ width: "100%" }}
                />
              </td>

              <td style={{ padding: "8px" }}>
                <input
                  type="text"
                  value={p.Description}
                  onChange={(e) =>
                    handleUpdate(p.ProductId, "Description", e.target.value)
                  }
                  style={{ width: "100%" }}
                />
              </td>

              <td style={{ padding: "8px" }}>
                <input
                  type="number"
                  step="0.01"
                  value={p.Price}
                  onChange={(e) =>
                    handleUpdate(p.ProductId, "Price", e.target.value)
                  }
                  style={{ width: 80 }}
                />
              </td>

              <td style={{ padding: "8px" }}>
                <input
                  type="text"
                  value={p.Category}
                  onChange={(e) =>
                    handleUpdate(p.ProductId, "Category", e.target.value)
                  }
                  style={{ width: 100 }}
                />
              </td>

              <td style={{ padding: "8px", textAlign: "center" }}>
                <input
                  type="checkbox"
                  checked={p.IsAvailable}
                  onChange={(e) =>
                    handleUpdate(
                      p.ProductId,
                      "IsAvailable",
                      e.target.checked
                    )
                  }
                />
              </td>

              <td style={{ padding: "8px" }}>
                <button onClick={() => handleDelete(p.ProductId)}>
                  Șterge
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
